    h_dVz_p_APID_epCD = new TH1D("dVz_p_APID_epCD", "Vertex correlation between CD proton and electron (After PID);dV^{p}_{z}=V^{p}_{z}-V^{e}_{z} [cm];Counts", 50, -8, 8);
    HistoList.push_back(h_dVz_p_APID_epCD);
    h_Chi2pid_p_APID_epCD = new TH1D("Chi2pid_p_APID_epCD", "CD Proton #chi^{2}_{p} (After PID);#chi^{2}_{p};Counts", 50, -6, 6);
    HistoList.push_back(h_Chi2pid_p_APID_epCD);

    h_dbeta_p_VS_P_p_BPID_epFD = new TH2D("dbeta_p_VS_P_p_BPID_epFD", "#Delta#beta_{p} vs FD proton momentum (Before PID);P_{p} [GeV/c];#Delta#beta_{p}", 50, 0, 3, 50, -0.2, 0.2);
    HistoList.push_back(h_dbeta_p_VS_P_p_BPID_epFD);
    h_dVz_p_BPID_epFD = new TH1D("dVz_p_BPID_epFD", "Vertex correlation between FD proton and electron (Before PID);dV^{p}_{z}=V^{p}_{z}-V^{e}_{z} [cm];Counts", 50, -8, 8);
    HistoList.push_back(h_dVz_p_BPID_epFD);
    h_Chi2pid_p_BPID_epFD = new TH1D("Chi2pid_p_BPID_epFD", "FD Proton #chi^{2}_{p} (Before PID);#chi^{2}_{p};Counts", 50, -6, 6);
    HistoList.push_back(h_Chi2pid_p_BPID_epFD);
    h_dbeta_p_VS_P_p_APID_epFD = new TH2D("dbeta_p_VS_P_p_APID_epFD", "#Delta#beta_{p} vs FD proton momentum (After PID);P_{p} [GeV/c];#Delta#beta_{p}", 50, 0, 3, 50, -0.2, 0.2);
    HistoList.push_back(h_dbeta_p_VS_P_p_APID_epFD);
